/** 授权类型一级 */
DELETE FROM SYS_DATADICT_LIST where DICT_CODE='RSK_AUTHORIZE_TYPE1';

/** 授权类型二级 */
DELETE FROM SYS_DATADICT_LIST where DICT_CODE='RSK_AUTHORIZE_TYPE2';


/** 授权数据字典关联 */
DELETE FROM SYS_DATADICT_LIST_LINK where DICT_CODE = 'RSK_AUTHORIZE_TYPE2' and LINKED_DICT_CODE = 'RSK_AUTHORIZE_TYPE1';


DELETE FROM SYS_DATADICT_LIST_LINK where DICT_CODE = 'TRADE_PLACE' AND LINKED_DICT_CODE = 'RSK_AUTHORIZE_TYPE1';










/** 交易方向合并 */
delete from SYS_DATADICT_LIST where DICT_CODE = 'PS' and ITEM_CODE in ('01', '02', '03', '04', '05', '06');


DELETE FROM SYS_DATADICT_LIST_LINK where DICT_CODE = 'PS' and LINKED_DICT_CODE = 'RSK_AUTHORIZE_TYPE1';























